function e(e){if(e<=0)return`0:00:00`;let t=Math.floor(e/1e3),n=Math.floor(t/3600),r=Math.floor(t%3600/60),i=t%60;return`${n}:${String(r).padStart(2,`0`)}:${String(i).padStart(2,`0`)}`}function t(e){return`${Number(e).toFixed(1)} km`}function n(e){let t=Date.now()-new Date(e).getTime(),n=Math.floor(t/6e4);if(n<1)return`just now`;if(n<60)return`${n} min ago`;let r=Math.floor(n/60);if(r<24)return`${r} hr${r>1?`s`:``} ago`;let i=Math.floor(r/24);return`${i} day${i>1?`s`:``} ago`}export{t as n,n as r,e as t};